sys_script.script:
(function executeRule(current, previous) {
    var currentStatus = current.getValue('status');

    if (currentStatus === 'completed' || currentStatus === 'cancelled') {
        var fieldsToProtect = ['customer', 'tyre_type', 'request_type', 'quantity', 'vehicle_make', 'vehicle_model', 'priority'];

        for (var i = 0; i < fieldsToProtect.length; i++) {
            var field = fieldsToProtect[i];
            if (current.getValue(field) !== previous.getValue(field)) {
                gs.addErrorMessage('Cannot modify "' + field + '" on a ' + currentStatus + ' request.');
                current.setAbortAction(true);
                return;
            }
        }
    }
})(current, previous);
